 99	        </tr>
100	        {% if not is_hidden %}
101	        {% for row in rows %}
102	        {% set tail = row.aircraft.tail_number %}
103	        <tr class="aircraft"{% if aircraft and aircraft.id == row.aircraft.id %} aria-current="true"{% endif %}>
104	          <th scope="row" class="tail"><a href="{{ link(tail=tail) }}">{{ tail }}</a></th>
105	          <td>
106	            {% if row.open_writeups %}
107	            <ul class="row-writeups">
108	              {% for writeup in row.open_writeups %}
109	              <li><span class="severity severity-{{ writeup.severity }}">{{ writeup.severity }}</span><span>{{ writeup.description }}</span></li>
110	              {% endfor %}
111	            </ul>
112	            {% else %}
113	            <p class="no-writeups">No open write-ups</p>
114	            {% endif %}
115	          </td>
116	          <td class="attention">
117	            {%- if row.is_overdue(today) or row.needs_scheduling -%}
118	            <div class="flags">
119	              {% if row.is_overdue(today) %}<span class="flag">Overdue</span>{% endif %}
120	              {% if row.needs_scheduling %}<span class="flag">Needs scheduling</span>{% endif %}
121	            </div>
122	            {%- endif -%}
123	          </td>
124	        </tr>
125	        {% else %}
126	        <tr><td colspan="3" class="empty">{% if query %}No {{ key }} aircraft match “{{ query }}”.{% else %}No aircraft {{ key }}.{% endif %}</td></tr>
127	        {% endfor %}
128	        {% endif %}
129	      </tbody>
130	      {% endfor %}
131	      {% endif %}
132	    </table>
133	  </main>
134	
135	  {% if aircraft %}
136	  <aside class="panel" aria-labelledby="panel-title">
137	    <a class="panel-close" href="{{ link(tail='') }}">
138	      <span class="wide-only">Close</span><span class="narrow-only">Back to fleet</span>
139	    </a>
140	
141	    <header class="panel-head">
142	      <h2 id="panel-title">{{ aircraft.tail_number }}</h2>
143	      {% if status.cleared %}
144	      <p class="status status-cleared">Cleared to fly</p>
145	      <p class="panel-reason">No open High write-ups.</p>
146	      {% else %}
147	      <p class="status status-grounded">Grounded</p>
148	      <p class="panel-reason">{{ status.grounding | length }} open High write-up{{ "s" if status.grounding | length > 1 }} must be resolved or canceled.</p>
149	      {% endif %}
150	    </header>
151	
152	    <details class="file-writeup"{% if failed(["file"]) %} open{% endif %}>
153	      <summary class="button">Create write-up</summary>
154	      <form method="post" action="/aircraft/{{ aircraft.id }}/writeups{{ form_query }}">
155	        {{ error_for(["file"]) }}
156	        <fieldset class="field">
157	          <legend>Severity</legend>
158	          <div class="choices">
159	            {% for severity in Severity %}
160	            <label><input type="radio" name="severity" value="{{ severity }}" required{% if kept('file', 'severity') == severity %} checked{% endif %}> {{ severity | capitalize }}</label>
161	            {% endfor %}
162	          </div>
163	        </fieldset>
164	        <label class="field">
165	          <span>What's wrong</span>
166	          <textarea name="description" rows="3" required>{{ kept("file", "description") }}</textarea>
167	        </label>
168	        <label class="field">
169	          <span>Scheduled date (optional)</span>
170	          {{ date_input("file", none, required=false) }}
171	        </label>
172	        {{ name_field("file", "reported_by") }}
173	        <button class="button">Submit</button>
174	      </form>
175	    </details>
176	
177	    <section class="open-writeups" aria-labelledby="open-title">
178	      <h3 id="open-title">Open write-ups <span>{{ status.open_writeups | length }}</span></h3>
179	      {% for writeup in status.open_writeups %}
180	      {% set id = writeup.id %}
181	      <article class="writeup writeup-{{ writeup.severity }}" id="writeup-{{ id }}">
182	        <div class="card-top">
183	          {% call edit(writeup, "severity", "severity") %}
184	          <summary class="severity severity-{{ writeup.severity }}" aria-label="Severity {{ writeup.severity }}, change it">{{ writeup.severity }}</summary>
185	          <form class="popover" method="post" action="/writeups/{{ id }}/severity{{ form_query }}">
186	            {{ error_for([id ~ "-severity"]) }}
187	            <label class="field">
188	              <span>Change severity to</span>
189	              <select name="severity" required>
190	                <option value="">Choose</option>
191	                {% for severity in Severity if severity != writeup.severity %}
192	                <option value="{{ severity }}"{% if kept(id ~ '-severity', 'severity') == severity %} selected{% endif %}>{{ severity | capitalize }}</option>
193	                {% endfor %}
194	              </select>
195	            </label>
196	            {{ note_field(id ~ "-severity", "Reason") }}
197	            {{ name_field(id ~ "-severity") }}
198	            <button class="button">Change severity</button>
199	          </form>
200	          {% endcall %}
201	
202	          <span class="state">{{ writeup.status | replace("_", " ") | capitalize }}</span>
203	
204	          <div class="corner">
205	            {% if is_overdue(writeup, today) %}<span class="flag">Overdue</span>{% endif %}
206	            {% if writeup.scheduled_date %}
207	            {% call edit(writeup, "schedule", "date", [id ~ "-schedule", id ~ "-unschedule"]) %}
208	            <summary class="date" aria-label="Scheduled {{ writeup.scheduled_date | day }}, reschedule">{{ writeup.scheduled_date | day }}</summary>
209	            <form class="popover popover-end" method="post" action="/writeups/{{ id }}/schedule{{ form_query }}">
210	              {{ error_for([id ~ "-schedule", id ~ "-unschedule"]) }}
211	              <label class="field"><span>Reschedule to</span>{{ date_input(id ~ "-schedule", writeup.scheduled_date) }}</label>
212	              {{ name_field(id ~ "-schedule") }}
213	              <div class="form-actions">
214	                <button class="button">Reschedule</button>
215	                {% if writeup.status == "scheduled" %}
216	                <button class="link-button" formaction="/writeups/{{ id }}/unschedule{{ form_query }}" formnovalidate>Remove date</button>
217	                {% endif %}
218	              </div>
219	            </form>
220	            {% endcall %}
221	            {% else %}
222	            <span class="flag">Needs scheduling</span>
223	            {% endif %}
224	          </div>
225	        </div>
226	
227	        {% call edit(writeup, "description", "description") %}
228	        <summary>{{ writeup.description }}</summary>
229	        <form method="post" action="/writeups/{{ id }}/description{{ form_query }}">
230	          {{ error_for([id ~ "-description"]) }}
231	          <label class="field">
232	            <span>Description</span>
233	            <textarea name="description" rows="3" required>{{ kept(id ~ '-description', 'description', writeup.description) }}</textarea>
234	          </label>
235	          {{ name_field(id ~ "-description") }}
236	          <button class="button">Save description</button>
237	        </form>
238	        {% endcall %}
239	
240	        <p class="meta">#{{ id }} · {{ writeup.reported_by }} · {{ writeup.reported_at | local_time(now) }}</p>
241	
242	        <div class="card-actions">
243	          {% if writeup.status == "unscheduled" %}
244	          {% call edit(writeup, "schedule", "step") %}
245	          <summary class="button">Schedule</summary>
246	          <form method="post" action="/writeups/{{ id }}/schedule{{ form_query }}">
247	            {{ error_for([id ~ "-schedule"]) }}
248	            <label class="field"><span>Scheduled date</span>{{ date_input(id ~ "-schedule", none) }}</label>
249	            {{ name_field(id ~ "-schedule") }}
250	            <button class="button">Schedule</button>
251	          </form>
252	          {% endcall %}
253	          {% elif writeup.status == "scheduled" %}
254	          {% call edit(writeup, "start", "step") %}
255	          <summary class="button">Start work</summary>
256	          <form method="post" action="/writeups/{{ id }}/start{{ form_query }}">
257	            {{ error_for([id ~ "-start"]) }}
258	            {{ name_field(id ~ "-start") }}
259	            <button class="button">Start work</button>
260	          </form>
261	          {% endcall %}
262	          {% else %}
263	          {% call edit(writeup, "resolve", "step") %}
264	          <summary class="button">Resolve</summary>
265	          <form method="post" action="/writeups/{{ id }}/resolve{{ form_query }}">
266	            {{ error_for([id ~ "-resolve"]) }}
267	            {{ note_field(id ~ "-resolve", "What was done") }}
268	            {{ name_field(id ~ "-resolve") }}
269	            <button class="button">Resolve</button>
270	          </form>
271	          {% endcall %}
272	          {% endif %}
273	
274	          {% call edit(writeup, "cancel", "cancel") %}
275	          <summary class="cancel-link">Cancel write-up</summary>
276	          <form class="popover popover-end" method="post" action="/writeups/{{ id }}/cancel{{ form_query }}">
277	            {{ error_for([id ~ "-cancel"]) }}
278	            {{ note_field(id ~ "-cancel", "Why cancel it") }}
279	            {{ name_field(id ~ "-cancel") }}
280	            <button class="button">Cancel write-up</button>
281	          </form>
282	          {% endcall %}
283	        </div>
284	      </article>
285	      {% else %}
286	      <p class="empty">No open write-ups.</p>
287	      {% endfor %}
288	    </section>
289	
290	    <section class="history" aria-labelledby="history-title">
291	      <h3 id="history-title">History</h3>
292	      <ol class="timeline">
293	        {% for entry in timeline %}
294	        <li>
295	          <p class="when"><time>{{ entry.at | local_time(now) }}</time> · {{ entry.actor }}</p>
296	          <p>{{ event_text(entry) }}</p>
297	          {% if entry.event and entry.event.note %}<p class="note">{{ entry.event.note }}</p>{% endif %}
298	          <p class="ref">#{{ entry.writeup.id }} {{ entry.writeup.description }}</p>
299	        </li>
300	        {% else %}
301	        <li class="empty">Nothing has been filed against this aircraft.</li>
302	        {% endfor %}
303	      </ol>
304	    </section>
305	  </aside>
306	  {% endif %}
307	
308	</div>
309	<script src="/static/scroll.js"></script>
310	</body>
311	</html>

